// 🧭 Navigation guide: every formula in the course with explanations, grouped by topic (t = TOPICS index).
// Item: {id, n:[no,en] name, f:[no,en] formula HTML, e:[no,en] explanation HTML, ex?:[no,en] worked example}
const GUIDE = (() => {
const S = s => [s, s];
const SUM = "Σ", y_ = "y<sub>pred</sub>";
return [
// ===== 0 Data & preprocessing =====
{t:0, items:[
 {id:"g-minmax", n:["Min-max-skalering","Min-max scaling"],
  f:["$x' = \\frac{x - \\min}{\\max - \\min}$", "$x' = \\frac{x - \\min}{\\max - \\min}$"],
  e:["Skalerer en feature til [0, 1] (<code>MinMaxScaler</code>). min og max hentes <b>bare fra treningsdataene</b>, og testdata får samme transformasjon. Testverdier utenfor treningsintervallet havner derfor utenfor [0, 1]. Følsom for outliere, fordi de bestemmer min og max.","Scales a feature to [0, 1] (<code>MinMaxScaler</code>). min and max come <b>from the training data only</b>, and test data get the same transform. Test values outside the training range therefore end up outside [0, 1]. Sensitive to outliers, because they set min and max."],
  ex:["min = 12, max = 72, x = 27: (27 − 12)/60 = 0,25.","min = 12, max = 72, x = 27: (27 − 12)/60 = 0.25."]},
 {id:"g-zscore", n:["Standardisering (z-score)","Standardisation (z-score)"],
  f:["$z = \\frac{x - \\mu}{\\sigma} \\iff x = \\mu + z\\,\\sigma$", "$z = \\frac{x - \\mu}{\\sigma} \\iff x = \\mu + z\\,\\sigma$"],
  e:["Gir en feature snitt 0 og standardavvik 1 (<code>StandardScaler</code>). μ og σ fra treningsdataene. Del på σ (standardavviket), ikke σ² (variansen). Formelen baklengs (<code>inverse_transform</code>) gir tilbake originalverdien.","Gives a feature mean 0 and standard deviation 1 (<code>StandardScaler</code>). μ and σ from the training data. Divide by σ (the standard deviation), not σ² (the variance). The formula backwards (<code>inverse_transform</code>) gives back the original value."],
  ex:["μ = 50, σ = 8, x = 38: z = −12/8 = −1,5.","μ = 50, σ = 8, x = 38: z = −12/8 = −1.5."]},
 {id:"g-robust", n:["Robust skalering","Robust scaling"],
  f:["$x' = \\frac{x - \\text{median}}{\\text{IQR}}, \\qquad \\text{IQR} = Q_3 - Q_1$", "$x' = \\frac{x - \\text{median}}{\\text{IQR}}, \\qquad \\text{IQR} = Q_3 - Q_1$"],
  e:["Bruker median og interkvartilbredde, som nesten ikke påvirkes av noen få ekstreme verdier. Velg denne når dataene har outliere. Både min-max og z-score dras av dem.","Uses the median and the interquartile range, which barely change because of a few extreme values. Choose it when the data have outliers. Both min-max and z-score are pulled by them."]},
 {id:"g-onehot", n:["Antall kolonner etter koding","Number of columns after encoding"],
  f:["One-hot: $k$ kolonner for en nominell feature med $k$ verdier ($k - 1$ med drop-first)<br>Ordinal / label encoding: 1 kolonne · numerisk: 1 kolonne", "One-hot: $k$ columns for a nominal feature with $k$ values ($k - 1$ with drop-first)<br>Ordinal / label encoding: 1 column · numeric: 1 column"],
  e:["Nominelle kategorier (farge, land) har ingen rekkefølge og bør one-hot-kodes. Ordinale (S/M/L) har en naturlig rekkefølge og kan få ett tall hver. Numeriske features beholdes.","Nominal categories (colour, country) have no order and should be one-hot encoded. Ordinal ones (S/M/L) have a natural order and can get one number each. Numeric features are kept."],
  ex:["4 farger + 6 land + størrelse (ordinal) + alder = 4 + 6 + 1 + 1 = 12 kolonner.","4 colours + 6 countries + size (ordinal) + age = 4 + 6 + 1 + 1 = 12 columns."]},
 {id:"g-impute", n:["Gjennomsnitt og median (imputering)","Mean and median (imputation)"],
  f:["$\\bar{x} = \\frac{1}{n} \\sum_i x_i$ &nbsp; (over de $n$ kjente verdiene)<br>median = midterste verdi i sortert rekkefølge (snitt av de to midterste hvis $n$ er partall)", "$\\bar{x} = \\frac{1}{n} \\sum_i x_i$ &nbsp; (over the $n$ known values)<br>median = the middle value in sorted order (mean of the two middle ones if $n$ is even)"],
  e:["Manglende verdier kan fylles inn med snitt eller median av de <i>kjente</i> verdiene, beregnet på treningsdataene. Del på antall kjente verdier. Medianen er mer robust mot ekstreme verdier. <code>dropna()</code> fjerner i stedet hele rader.","Missing values can be filled in with the mean or median of the <i>known</i> values, computed on the training data. Divide by the number of known values. The median is more robust to extreme values. <code>dropna()</code> instead removes whole rows."],
  ex:["Age = 22, 38, 26, 35, 35, ?, 54, 2, 27: snitt = 239/8 ≈ 29,88, median = (27 + 35)/2 = 31.","Age = 22, 38, 26, 35, 35, ?, 54, 2, 27: mean = 239/8 ≈ 29.88, median = (27 + 35)/2 = 31."]},
 {id:"g-split", n:["Trenings-, validerings- og testsett","Training, validation and test sets"],
  f:["<code>train_test_split(…, test_size=t)</code>: andelen $t$ av radene som sendes inn går til den andre delen<br>$n_{\\text{test}} = t_1\\, n \\qquad n_{\\text{val}} = t_2\\, (n - n_{\\text{test}}) \\qquad n_{\\text{train}} = \\text{resten}$", "<code>train_test_split(…, test_size=t)</code>: the share $t$ of the rows passed in goes to the second part<br>$n_{\\text{test}} = t_1\\, n \\qquad n_{\\text{val}} = t_2\\, (n - n_{\\text{test}}) \\qquad n_{\\text{train}} = \\text{the rest}$"],
  e:["Trening tilpasser parametrene, validering velger hyperparametre, og test brukes bare til den endelige rapporten. Splitter du to ganger, ser det andre kallet bare restene etter det første. Ved ubalanserte klasser: <code>stratify=y</code>.","Training fits the parameters, validation picks hyperparameters, and test is only used for the final report. If you split twice, the second call only sees what is left after the first. With imbalanced classes: <code>stratify=y</code>."],
  ex:["2000 rader, test_size 0,2 og så 0,25: test 400, validering 0,25·1600 = 400, trening 1200.","2000 rows, test_size 0.2 and then 0.25: test 400, validation 0.25·1600 = 400, training 1200."]}
]},
// ===== 1 Logistic regression & gradient descent =====
{t:1, items:[
 {id:"g-linz", n:["Lineær kombinasjon","Linear combination"],
  f:["$z = \\sum_{i=1}^{n} w_i x_i + b = \\mathbf{w} \\cdot \\mathbf{x} + b$", "$z = \\sum_{i=1}^{n} w_i x_i + b = \\mathbf{w} \\cdot \\mathbf{x} + b$"],
  e:["Hver vekt w<sub>i</sub> sier hvor viktig feature x<sub>i</sub> er, og b er biasen (skjæringspunktet). z er et tall, ikke en vektor (prikkprodukt), og kan ha hvilken som helst verdi.","Each weight w<sub>i</sub> says how important feature x<sub>i</sub> is, and b is the bias (intercept). z is a number, not a vector (dot product), and can take any value."]},
 {id:"g-sigmoid", n:["Sigmoid (logistisk funksjon)","Sigmoid (logistic function)"],
  f:["$\\sigma(z) = \\frac{1}{1 + e^{-z}}$<br>$y_{\\text{pred}} = \\sigma(\\mathbf{w}\\cdot\\mathbf{x} + b) \\qquad \\sigma'(z) = \\sigma(z)\\left(1 - \\sigma(z)\\right)$", "$\\sigma(z) = \\frac{1}{1 + e^{-z}}$<br>$y_{\\text{pred}} = \\sigma(\\mathbf{w}\\cdot\\mathbf{x} + b) \\qquad \\sigma'(z) = \\sigma(z)\\left(1 - \\sigma(z)\\right)$"],
  e:["Klemmer z inn i (0, 1), slik at " + y_ + " kan tolkes som p(y = 1 | x). σ(0) = 0,5, store positive z gir nær 1, store negative nær 0. Den deriverte brukes i backpropagation.","Squeezes z into (0, 1), so " + y_ + " can be read as p(y = 1 | x). σ(0) = 0.5, large positive z give close to 1, large negative close to 0. The derivative is used in backpropagation."],
  ex:["w = (2, −1), b = 0,5, x = (1, 3): z = 2 − 3 + 0,5 = −0,5, σ(−0,5) ≈ 0,38.","w = (2, −1), b = 0.5, x = (1, 3): z = 2 − 3 + 0.5 = −0.5, σ(−0.5) ≈ 0.38."]},
 {id:"g-threshold", n:["Klassifiseringsterskel","Classification threshold"],
  f:["$\\hat{y} = 1$ hvis $y_{\\text{pred}} > \\text{terskel}$, ellers 0<br>$\\sigma(z) = p \\iff z = \\ln\\frac{p}{1 - p}$", "$\\hat{y} = 1$ if $y_{\\text{pred}} > \\text{threshold}$, otherwise 0<br>$\\sigma(z) = p \\iff z = \\ln\\frac{p}{1 - p}$"],
  e:["Standard er 0,5, som svarer til z = 0. Høyere terskel gir færre positive (recall ned, precision som regel opp). Lavere terskel gir flere positive. Terskelen endrer ikke modellen, bare hvordan prediksjonene tolkes.","The default is 0.5, which corresponds to z = 0. A higher threshold gives fewer positives (recall down, precision usually up). A lower threshold gives more positives. The threshold does not change the model, only how the predictions are read."],
  ex:["w = 2, b = −3, terskel 0,8: z = ln 4 ≈ 1,39, så x = (1,39 + 3)/2 ≈ 2,19.","w = 2, b = −3, threshold 0.8: z = ln 4 ≈ 1.39, so x = (1.39 + 3)/2 ≈ 2.19."]},
 {id:"g-bce", n:["Binær cross-entropy (log loss)","Binary cross-entropy (log loss)"],
  f:["$L(y_{\\text{pred}}, y) = -y \\ln y_{\\text{pred}} - (1 - y)\\ln(1 - y_{\\text{pred}})$", "$L(y_{\\text{pred}}, y) = -y \\ln y_{\\text{pred}} - (1 - y)\\ln(1 - y_{\\text{pred}})$"],
  e:["Minus log-likelihood. For y = 1 teller bare −ln " + y_ + ", og for y = 0 bare −ln(1 − " + y_ + "). Tapet er 0 ved perfekt prediksjon og vokser mot ∞ når modellen er sikker og tar feil. Bruk naturlig logaritme.","Minus the log-likelihood. For y = 1 only −ln " + y_ + " counts, and for y = 0 only −ln(1 − " + y_ + "). The loss is 0 for a perfect prediction and grows towards ∞ when the model is confident and wrong. Use the natural logarithm."],
  ex:["y = 1, " + y_ + " = 0,8: L = −ln 0,8 ≈ 0,22.","y = 1, " + y_ + " = 0.8: L = −ln 0.8 ≈ 0.22."]},
 {id:"g-avgloss", n:["Gjennomsnittlig tap (treningsmål)","Average loss (training objective)"],
  f:["$\\hat{\\theta} = \\arg\\min_\\theta \\frac{1}{N} \\sum_{i=1}^{N} L\\left(f(x^{(i)}; \\theta),\\, y^{(i)}\\right), \\qquad \\theta = (\\mathbf{w}, b)$", "$\\hat{\\theta} = \\arg\\min_\\theta \\frac{1}{N} \\sum_{i=1}^{N} L\\left(f(x^{(i)}; \\theta),\\, y^{(i)}\\right), \\qquad \\theta = (\\mathbf{w}, b)$"],
  e:["Trening betyr å finne parametrene som minimerer snittet av tapet over alle N treningspunkter. Husk å dele på N.","Training means finding the parameters that minimise the mean loss over all N training points. Remember to divide by N."]},
 {id:"g-grad-logreg", n:["Gradienten for logistisk regresjon","The gradient for logistic regression"],
  f:["$\\frac{\\partial L}{\\partial w_j} = (y_{\\text{pred}} - y)\\, x_j \\qquad \\frac{\\partial L}{\\partial b} = y_{\\text{pred}} - y$", "$\\frac{\\partial L}{\\partial w_j} = (y_{\\text{pred}} - y)\\, x_j \\qquad \\frac{\\partial L}{\\partial b} = y_{\\text{pred}} - y$"],
  e:["Med cross-entropy og sigmoid blir gradienten bare feilen ganger inputen. Negativ gradient betyr at tapet minker når parameteren øker.","With cross-entropy and sigmoid, the gradient is just the error times the input. A negative gradient means the loss decreases when the parameter increases."],
  ex:["x = (2, 1), y = 1, " + y_ + " = 0,5: ∂L/∂w = (−1; −0,5), ∂L/∂b = −0,5.","x = (2, 1), y = 1, " + y_ + " = 0.5: ∂L/∂w = (−1, −0.5), ∂L/∂b = −0.5."]},
 {id:"g-gd", n:["Gradient descent","Gradient descent"],
  f:["$\\theta_{t+1} = \\theta_t - \\eta\\, \\frac{\\partial L}{\\partial \\theta}$", "$\\theta_{t+1} = \\theta_t - \\eta\\, \\frac{\\partial L}{\\partial \\theta}$"],
  e:["Gradienten peker mot økende tap, så vi går motsatt vei (minustegnet). η er læringsraten, en hyperparameter. For stor η gir oscillasjon eller divergens. For liten η gir svært langsom læring. Oppdater alle parametre, også b.","The gradient points towards increasing loss, so we move the opposite way (the minus sign). η is the learning rate, a hyperparameter. Too large an η gives oscillation or divergence. Too small an η gives very slow learning. Update every parameter, b too."],
  ex:["w = 3, ∂L/∂w = 4, η = 0,25: w = 3 − 1 = 2.","w = 3, ∂L/∂w = 4, η = 0.25: w = 3 − 1 = 2."]}
]},
// ===== 2 Classification metrics =====
{t:2, items:[
 {id:"g-cm", n:["Confusion matrix","Confusion matrix"],
  f:["$TP$ = sann positiv · $FN$ = sann positiv, predikert negativ · $FP$ = sann negativ, predikert positiv · $TN$ = sann negativ<br>$P = TP + FN$ (alle positive) · $N = TN + FP$ (alle negative)", "$TP$ = true positive · $FN$ = actually positive, predicted negative · $FP$ = actually negative, predicted positive · $TN$ = true negative<br>$P = TP + FN$ (all positives) · $N = TN + FP$ (all negatives)"],
  e:["Riktige prediksjoner ligger på diagonalen, feil utenfor. Sjekk alltid om radene er sann eller predikert klasse, og hvilken klasse som er positiv.","Correct predictions lie on the diagonal, errors off it. Always check whether the rows are the true or the predicted class, and which class is positive."]},
 {id:"g-recall", n:["Recall / sensitivitet / TPR","Recall / sensitivity / TPR"],
  f:["$\\text{TPR} = \\text{Recall} = \\frac{TP}{P} = \\frac{TP}{TP + FN}$", "$\\text{TPR} = \\text{Recall} = \\frac{TP}{P} = \\frac{TP}{TP + FN}$"],
  e:["Andelen av de faktisk positive som blir funnet. Viktig når falske negative er dyre (alvorlig sykdom, screening). Deler på <i>sanne</i> positive.","The share of the actual positives that are found. Important when false negatives are costly (serious disease, screening). Divides by the <i>actual</i> positives."]},
 {id:"g-spec", n:["Spesifisitet / TNR","Specificity / TNR"],
  f:["$\\text{TNR} = \\frac{TN}{N} = \\frac{TN}{TN + FP}$", "$\\text{TNR} = \\frac{TN}{N} = \\frac{TN}{TN + FP}$"],
  e:["Andelen av de faktisk negative som blir korrekt klassifisert som negative.","The share of the actual negatives that are correctly classified as negative."]},
 {id:"g-fpr", n:["False positive rate","False positive rate"],
  f:["$\\text{FPR} = \\frac{FP}{N} = \\frac{FP}{FP + TN} = 1 - \\text{TNR}$", "$\\text{FPR} = \\frac{FP}{N} = \\frac{FP}{FP + TN} = 1 - \\text{TNR}$"],
  e:["Sannsynligheten for falsk alarm. Dette er x-aksen i ROC-kurven. Deler på alle negative, ikke på de predikert positive (det ville vært 1 − precision).","The probability of a false alarm. This is the x-axis of the ROC curve. Divides by all negatives, not by the predicted positives (that would be 1 − precision)."]},
 {id:"g-precision", n:["Precision / PPV","Precision / PPV"],
  f:["$\\text{Precision} = \\frac{TP}{TP + FP}$", "$\\text{Precision} = \\frac{TP}{TP + FP}$"],
  e:["Andelen av de predikert positive som faktisk er positive. Viktig når falske alarmer er dyre. Avhenger av klassefordelingen: med få positive kan precision bli lav selv med lav FPR.","The share of the predicted positives that are actually positive. Important when false alarms are costly. Depends on the class distribution: with few positives, precision can be low even with a low FPR."]},
 {id:"g-accuracy", n:["Accuracy (treffsikkerhet)","Accuracy"],
  f:["$\\text{Accuracy} = \\frac{TP + TN}{TP + TN + FP + FN}$", "$\\text{Accuracy} = \\frac{TP + TN}{TP + TN + FP + FN}$"],
  e:["Andelen riktige prediksjoner. Misvisende ved ubalanserte klasser: en modell som alltid sier «negativ» får 95 % med 5 % positive, men recall 0.","The share of correct predictions. Misleading with imbalanced classes: a model that always says “negative” gets 95 % with 5 % positives, but recall 0."]},
 {id:"g-f1", n:["F1-score","F1 score"],
  f:["$F_1 = \\frac{2 \\cdot \\text{Precision} \\cdot \\text{Recall}}{\\text{Precision} + \\text{Recall}}$", "$F_1 = \\frac{2 \\cdot \\text{Precision} \\cdot \\text{Recall}}{\\text{Precision} + \\text{Recall}}$"],
  e:["Harmonisk snitt av precision og recall. Den blir lav hvis én av dem er lav. Precision = recall nøyaktig når FP = FN.","The harmonic mean of precision and recall. It is low if either of them is low. Precision = recall exactly when FP = FN."],
  ex:["TP = 40, FN = 20, FP = 10: P = 0,8, R ≈ 0,667, F1 ≈ 0,73.","TP = 40, FN = 20, FP = 10: P = 0.8, R ≈ 0.667, F1 ≈ 0.73."]},
 {id:"g-auc", n:["ROC-kurve og AUC","ROC curve and AUC"],
  f:["ROC: $(\\text{FPR}, \\text{TPR})$ for alle terskler fra 1 til 0, fra $(0, 0)$ til $(1, 1)$<br>$\\text{AUC} = P\\left(s(x^+) > s(x^-)\\right) = \\frac{\\text{antall par der positiv har høyest skår}}{n^+ \\cdot n^-}$", "ROC: $(\\text{FPR}, \\text{TPR})$ for every threshold from 1 to 0, from $(0, 0)$ to $(1, 1)$<br>$\\text{AUC} = P\\left(s(x^+) > s(x^-)\\right) = \\frac{\\text{number of pairs where the positive scores higher}}{n^+ \\cdot n^-}$"],
  e:["Diagonalen er tilfeldig gjetning (AUC = 0,5), og maks er 1. AUC < 0,5 betyr systematisk feil rangering; snur du prediksjonene får du 1 − AUC. Ved sterk ubalanse er en precision–recall-kurve ofte mer informativ.","The diagonal is random guessing (AUC = 0.5), and the maximum is 1. AUC < 0.5 means systematically wrong ranking; flipping the predictions gives 1 − AUC. Under strong imbalance a precision–recall curve is often more informative."],
  ex:["Positive 0,9, 0,8, 0,4 og negative 0,7, 0,3, 0,2: 8 av 9 par riktig, AUC ≈ 0,89.","Positives 0.9, 0.8, 0.4 and negatives 0.7, 0.3, 0.2: 8 of 9 pairs right, AUC ≈ 0.89."]}
]},
// ===== 3 Bayes & imbalanced data =====
{t:3, items:[
 {id:"g-bayes", n:["Bayes' teorem","Bayes' theorem"],
  f:["$p(C_k \\mid x) = \\frac{p(x \\mid C_k)\\, p(C_k)}{p(x)}$", "$p(C_k \\mid x) = \\frac{p(x \\mid C_k)\\, p(C_k)}{p(x)}$"],
  e:["p(C<sub>k</sub>) er prior (klassefordelingen), p(x|C<sub>k</sub>) er likelihood, p(x) er evidens og p(C<sub>k</sub>|x) er posterior. p(x) er lik for alle klasser og sikrer at posteriorene summerer til 1.","p(C<sub>k</sub>) is the prior (the class distribution), p(x|C<sub>k</sub>) is the likelihood, p(x) is the evidence and p(C<sub>k</sub>|x) is the posterior. p(x) is the same for all classes and makes the posteriors sum to 1."]},
 {id:"g-totalprob", n:["Total sannsynlighet (evidensen)","Total probability (the evidence)"],
  f:["$p(x) = \\sum_k p(x \\mid C_k)\\, p(C_k)$<br>To klasser: $p(x) = p(x \\mid C)\\, p(C) + p(x \\mid \\neg C)\\, p(\\neg C)$", "$p(x) = \\sum_k p(x \\mid C_k)\\, p(C_k)$<br>Two classes: $p(x) = p(x \\mid C)\\, p(C) + p(x \\mid \\neg C)\\, p(\\neg C)$"],
  e:["Typisk i testoppgaver: p(+) = sensitivitet · prevalens + falsk-positiv-rate · (1 − prevalens). Med lav prevalens kan p(syk | +) bli overraskende lav.","Typical in test questions: p(+) = sensitivity · prevalence + false-positive rate · (1 − prevalence). With low prevalence p(sick | +) can be surprisingly low."],
  ex:["Prevalens 1 %, sensitivitet 90 %, FPR 5 %: 0,009 / (0,009 + 0,0495) ≈ 15,4 %.","Prevalence 1 %, sensitivity 90 %, FPR 5 %: 0.009 / (0.009 + 0.0495) ≈ 15.4 %."]},
 {id:"g-naivebayes", n:["Naiv Bayes","Naive Bayes"],
  f:["$p(C_k \\mid x) \\propto p(C_k) \\prod_{i=1}^{n} p(x_i \\mid C_k)$<br>$\\hat{y} = \\arg\\max_k\\, p(C_k) \\prod_i p(x_i \\mid C_k)$", "$p(C_k \\mid x) \\propto p(C_k) \\prod_{i=1}^{n} p(x_i \\mid C_k)$<br>$\\hat{y} = \\arg\\max_k\\, p(C_k) \\prod_i p(x_i \\mid C_k)$"],
  e:["Antar at featurene er uavhengige gitt klassen, slik at simultanfordelingen blir et produkt. Skårene er ikke kalibrerte sannsynligheter, men rekkefølgen er nok for argmax. Ikke glem prior.","Assumes the features are independent given the class, so the joint distribution becomes a product. The scores are not calibrated probabilities, but their order is enough for the argmax. Do not forget the prior."]},
 {id:"g-normalise", n:["Normalisering av posterior","Normalising the posterior"],
  f:["$p(C_k \\mid x) = \\frac{s_k}{\\sum_j s_j}, \\qquad s_k = p(C_k) \\prod_i p(x_i \\mid C_k)$", "$p(C_k \\mid x) = \\frac{s_k}{\\sum_j s_j}, \\qquad s_k = p(C_k) \\prod_i p(x_i \\mid C_k)$"],
  e:["Del hver skår på summen av skårene for å få sannsynligheter som summerer til 1. Den rå skåren s<sub>k</sub> er ikke en sannsynlighet.","Divide each score by the sum of the scores to get probabilities that sum to 1. The raw score s<sub>k</sub> is not a probability."],
  ex:["s<sub>spam</sub> = 0,4·0,5·0,6 = 0,12 og s<sub>ham</sub> = 0,6·0,1·0,3 = 0,018: p(spam|x) = 0,12/0,138 ≈ 0,87.","s<sub>spam</sub> = 0.4·0.5·0.6 = 0.12 and s<sub>ham</sub> = 0.6·0.1·0.3 = 0.018: p(spam|x) = 0.12/0.138 ≈ 0.87."]},
 {id:"g-prior-shift", n:["Bayes-grense og prior shift","Bayes boundary and prior shift"],
  f:["Velg $C = 1$ når $p(x \\mid C{=}1)\\, p(C{=}1) > p(x \\mid C{=}0)\\, p(C{=}0)$<br>To Gauss med $\\mu = \\mp 1$, $\\sigma = 1$: $x^* = -\\frac{1}{2} \\ln\\frac{p(C=1)}{p(C=0)}$", "Choose $C = 1$ when $p(x \\mid C{=}1)\\, p(C{=}1) > p(x \\mid C{=}0)\\, p(C{=}0)$<br>Two Gaussians with $\\mu = \\mp 1$, $\\sigma = 1$: $x^* = -\\frac{1}{2} \\ln\\frac{p(C=1)}{p(C=0)}$"],
  e:["Grensen ligger der de vektede tetthetene er like. Endres prior, flyttes grensen bort fra den hyppige klassen, så den «vinner» et større område. Ved skjeve klasser dominerer p(C<sub>k</sub>) prediksjonene (prior probability shift).","The boundary is where the weighted densities are equal. If the prior changes, the boundary moves away from the frequent class, so it “wins” a larger region. With imbalanced classes p(C<sub>k</sub>) dominates the predictions (prior probability shift)."]},
 {id:"g-resample", n:["Under- og oversampling","Under- and oversampling"],
  f:["Undersampling: $n_{\\text{maj}} \\to n_{\\min}$, totalt $2\\, n_{\\min}$<br>Oversampling: $n_{\\min} \\to n_{\\text{maj}}$, totalt $2\\, n_{\\text{maj}}$, duplikater $= n_{\\text{maj}} - n_{\\min}$", "Undersampling: $n_{\\text{maj}} \\to n_{\\min}$, total $2\\, n_{\\min}$<br>Oversampling: $n_{\\min} \\to n_{\\text{maj}}$, total $2\\, n_{\\text{maj}}$, duplicates $= n_{\\text{maj}} - n_{\\min}$"],
  e:["Undersampling kaster data og kan gi undertilpasning. Oversampling kopierer minoritetsklassen og kan gi overtilpasning. Teknikkene kan kombineres. Resample bare treningsdataene.","Undersampling throws data away and can cause underfitting. Oversampling copies the minority class and can cause overfitting. The techniques can be combined. Resample only the training data."],
  ex:["100 vs 1000: undersampling gir 200 totalt. Oversampling gir 2000 totalt, med 900 duplikater.","100 vs 1000: undersampling gives 200 in total. Oversampling gives 2000 in total, with 900 duplicates."]},
 {id:"g-classweights", n:["Klassevekter","Class weights"],
  f:["$w_c = \\frac{n}{K \\cdot n_c}$", "$w_c = \\frac{n}{K \\cdot n_c}$"],
  e:["n er antall eksempler, K antall klasser og n<sub>c</sub> antall i klasse c. Vektene er omvendt proporsjonale med klassestørrelsen, så sjeldne klasser får størst vekt (<code>class_weight=\"balanced\"</code>).","n is the number of examples, K the number of classes and n<sub>c</sub> the count in class c. The weights are inversely proportional to the class size, so rare classes get the largest weight (<code>class_weight=\"balanced\"</code>)."],
  ex:["9000 negative og 1000 positive: w<sub>pos</sub> = 10 000/(2·1000) = 5, w<sub>neg</sub> ≈ 0,56.","9000 negatives and 1000 positives: w<sub>pos</sub> = 10,000/(2·1000) = 5, w<sub>neg</sub> ≈ 0.56."]},
 {id:"g-weightedbce", n:["Vektet cross-entropy","Weighted cross-entropy"],
  f:["$L(y_{\\text{pred}}, y) = -w_1\\, y \\ln y_{\\text{pred}} - w_0\\, (1 - y) \\ln(1 - y_{\\text{pred}})$", "$L(y_{\\text{pred}}, y) = -w_1\\, y \\ln y_{\\text{pred}} - w_0\\, (1 - y) \\ln(1 - y_{\\text{pred}})$"],
  e:["w<sub>1</sub> vekter leddet for klasse y = 1 og w<sub>0</sub> leddet for y = 0. Større vekt på en klasse gjør feil på den dyrere, så modellen prioriterer den.","w<sub>1</sub> weights the term for class y = 1 and w<sub>0</sub> the term for y = 0. A larger weight on a class makes errors on it more costly, so the model prioritises it."],
  ex:["w<sub>1</sub> = 9, y = 1, " + y_ + " = 0,25: L = −9·ln 0,25 ≈ 12,48.","w<sub>1</sub> = 9, y = 1, " + y_ + " = 0.25: L = −9·ln 0.25 ≈ 12.48."]},
 {id:"g-curse", n:["Dimensjonsforbannelsen","The curse of dimensionality"],
  f:["Bins totalt $= b^d$ &nbsp; ($b$ bins per akse, $d$ dimensjoner)<br>Underkube med andel $r$ av volumet i $[0, 1]^d$: sidekant $e = r^{1/d}$", "Total bins $= b^d$ &nbsp; ($b$ bins per axis, $d$ dimensions)<br>Sub-cube with share $r$ of the volume in $[0, 1]^d$: edge $e = r^{1/d}$"],
  e:["Antall datapunkter du trenger vokser eksponentielt med d. I høye dimensjoner blir alle avstander omtrent like store, og «lokale» naboer er ikke lenger lokale.","The number of data points you need grows exponentially with d. In high dimensions all distances become about equal, and “local” neighbours are no longer local."],
  ex:["10 bins og 10 punkter per bin: d = 3 krever 10⁴ punkter. 10 % av en 10D-kube: e = 0,1<sup>0,1</sup> ≈ 0,79.","10 bins and 10 points per bin: d = 3 needs 10⁴ points. 10 % of a 10D cube: e = 0.1<sup>0.1</sup> ≈ 0.79."]}
]},
// ===== 4 Trees & ensembles =====
{t:4, items:[
 {id:"g-gini", n:["Gini-urenhet","Gini impurity"],
  f:["$\\text{Gini}(D) = 1 - \\sum_{i=1}^{k} p_i^2$", "$\\text{Gini}(D) = 1 - \\sum_{i=1}^{k} p_i^2$"],
  e:["Sannsynligheten for å klassifisere et tilfeldig punkt feil hvis du gjetter etter klassefordelingen i noden. For to klasser ligger den i [0, 0,5]: 0 er en ren node og 0,5 en jevn fordeling. Default i sklearn og billigere enn entropi.","The probability of misclassifying a random point if you guess according to the class distribution in the node. For two classes it lies in [0, 0.5]: 0 is a pure node and 0.5 an even split. The default in sklearn and cheaper than entropy."],
  ex:["[30, 20]: 1 − 0,6² − 0,4² = 0,48.","[30, 20]: 1 − 0.6² − 0.4² = 0.48."]},
 {id:"g-gini-split", n:["Gini etter en splitt","Gini after a split"],
  f:["$\\text{Gini}_f(D) = \\frac{n_1}{n} \\text{Gini}(D_1) + \\frac{n_2}{n} \\text{Gini}(D_2)$", "$\\text{Gini}_f(D) = \\frac{n_1}{n} \\text{Gini}(D_1) + \\frac{n_2}{n} \\text{Gini}(D_2)$"],
  e:["Vekt hvert barn med andelen punkter det får. Velg den featuren og verdien som gir <b>lavest</b> vektet urenhet. Et uvektet snitt er en vanlig feil.","Weight each child by the share of points it gets. Choose the feature and value with the <b>lowest</b> weighted impurity. An unweighted mean is a common mistake."],
  ex:["Rot 120 + 80 punkter med Gini 0,42 og 0,32: 0,6·0,42 + 0,4·0,32 = 0,38.","Root 120 + 80 points with Gini 0.42 and 0.32: 0.6·0.42 + 0.4·0.32 = 0.38."]},
 {id:"g-entropy", n:["Entropi","Entropy"],
  f:["$I(p_1, \\dots, p_k) = -\\sum_{i=1}^{k} p_i \\log_2(p_i)$", "$I(p_1, \\dots, p_k) = -\\sum_{i=1}^{k} p_i \\log_2(p_i)$"],
  e:["Usikkerheten i en fordeling. For to klasser er den 1 ved (0,5; 0,5) og 0 når alle er i samme klasse. Bruk log<sub>2</sub>, og 0·log 0 = 0.","The uncertainty in a distribution. For two classes it is 1 at (0.5, 0.5) and 0 when everything is in one class. Use log<sub>2</sub>, and 0·log 0 = 0."],
  ex:["p = 9, n = 5: I(9/14, 5/14) ≈ 0,94. [6, 2]: ≈ 0,81.","p = 9, n = 5: I(9/14, 5/14) ≈ 0.94. [6, 2]: ≈ 0.81."]},
 {id:"g-infogain", n:["Informasjonsgevinst","Information gain"],
  f:["$\\Delta I = I_{\\text{før}} - E[I_{\\text{etter}}]$<br>$E[I_{\\text{etter}}] = \\sum_{i=1}^{s} \\frac{p_i + n_i}{p + n}\\, I\\left(\\frac{p_i}{p_i + n_i}, \\frac{n_i}{p_i + n_i}\\right)$", "$\\Delta I = I_{\\text{before}} - E[I_{\\text{after}}]$<br>$E[I_{\\text{after}}] = \\sum_{i=1}^{s} \\frac{p_i + n_i}{p + n}\\, I\\left(\\frac{p_i}{p_i + n_i}, \\frac{n_i}{p_i + n_i}\\right)$"],
  e:["Hvor mye en splitt reduserer entropien. Velg splitten med <b>størst</b> ΔI. Barna vektes med sin andel av punktene.","How much a split reduces the entropy. Choose the split with the <b>largest</b> ΔI. The children are weighted by their share of the points."],
  ex:["[9, 5] → [4, 5] og [5, 0]: E[I<sub>etter</sub>] ≈ 0,64, ΔI ≈ 0,94 − 0,64 = 0,30.","[9, 5] → [4, 5] and [5, 0]: E[I<sub>after</sub>] ≈ 0.64, ΔI ≈ 0.94 − 0.64 = 0.30."]},
 {id:"g-regtree", n:["Splitt i regresjonstrær","Splits in regression trees"],
  f:["$\\text{Var}(D) = \\frac{1}{n} \\sum (y - \\bar{y})^2$<br>$\\text{Var}_{\\text{splitt}} = \\frac{n_1}{n} \\text{Var}(D_1) + \\frac{n_2}{n} \\text{Var}(D_2)$ &nbsp;·&nbsp; løvnoden predikerer $\\bar{y}$", "$\\text{Var}(D) = \\frac{1}{n} \\sum (y - \\bar{y})^2$<br>$\\text{Var}_{\\text{split}} = \\frac{n_1}{n} \\text{Var}(D_1) + \\frac{n_2}{n} \\text{Var}(D_2)$ &nbsp;·&nbsp; a leaf predicts $\\bar{y}$"],
  e:["Regresjonstrær velger splitten som gir lavest (vektet) varians, altså lavest MSE, i barna. Hver løvnode predikerer snittet av targets i sin region. Et binært tre med dybde d har høyst 2<sup>d</sup> løvnoder.","Regression trees choose the split that gives the lowest (weighted) variance, i.e. the lowest MSE, in the children. Each leaf predicts the mean of the targets in its region. A binary tree of depth d has at most 2<sup>d</sup> leaves."],
  ex:["{1, 2, 3} | {10, 11, 12}: 0,5·⅔ + 0,5·⅔ ≈ 0,67.","{1, 2, 3} | {10, 11, 12}: 0.5·⅔ + 0.5·⅔ ≈ 0.67."]},
 {id:"g-oob", n:["Bootstrap og out-of-bag","Bootstrap and out-of-bag"],
  f:["$P(\\text{out-of-bag}) = \\left(1 - \\frac{1}{n}\\right)^n \\to \\frac{1}{e} \\approx 0{,}368$ når $n \\to \\infty$", "$P(\\text{out-of-bag}) = \\left(1 - \\frac{1}{n}\\right)^n \\to \\frac{1}{e} \\approx 0.368$ as $n \\to \\infty$"],
  e:["I bagging trekkes n punkter <i>med tilbakelegging</i>. Hvert punkt har sannsynlighet 1 − 1/n for ikke å bli trukket i én trekning. Omtrent 37 % havner utenfor (out-of-bag) og kan brukes til validering.","In bagging, n points are drawn <i>with replacement</i>. Each point has probability 1 − 1/n of not being drawn in one draw. About 37 % end up out-of-bag and can be used for validation."],
  ex:["n = 10: 0,9<sup>10</sup> ≈ 34,9 %.","n = 10: 0.9<sup>10</sup> ≈ 34.9 %."]},
 {id:"g-adaboost", n:["AdaBoost: vekt per modell","AdaBoost: weight per model"],
  f:["$\\alpha = \\frac{1}{2} \\ln\\frac{1 - \\varepsilon}{\\varepsilon}$", "$\\alpha = \\frac{1}{2} \\ln\\frac{1 - \\varepsilon}{\\varepsilon}$"],
  e:["ε er den vektede feilraten til den svake modellen. Lav feil gir stor α (modellen stemmer tyngre), og ε = 0,5 gir α = 0. Feilklassifiserte punkter får økt vekt til neste modell, så modellene trenes sekvensielt.","ε is the weak model's weighted error rate. A low error gives a large α (the model's vote counts more), and ε = 0.5 gives α = 0. Misclassified points get a higher weight for the next model, so the models are trained sequentially."],
  ex:["ε = 0,2: α = ½·ln 4 ≈ 0,69.","ε = 0.2: α = ½·ln 4 ≈ 0.69."]},
 {id:"g-gboost", n:["Gradient boosting","Gradient boosting"],
  f:["Pseudo-residual: $g = -(y - F(x))$<br>$\\text{new\\_ensemble} = \\text{previous\\_ensemble} - \\text{learning\\_rate} \\cdot \\text{new\\_tree}$ &nbsp; ($\\text{new\\_tree}$ tilpasses $g$)", "Pseudo-residual: $g = -(y - F(x))$<br>$\\text{new\\_ensemble} = \\text{previous\\_ensemble} - \\text{learning\\_rate} \\cdot \\text{new\\_tree}$ &nbsp; ($\\text{new\\_tree}$ is fitted to $g$)"],
  e:["Hvert nye tre predikerer feilen til forrige ensemble, og ensemblet tar et lite steg mot target. Det er gradient descent i rommet av trær. AdaBoost vekter i stedet datapunkter.","Each new tree predicts the error of the previous ensemble, and the ensemble takes a small step towards the target. It is gradient descent in the space of trees. AdaBoost weights data points instead."],
  ex:["y = 10, F = 6, lr = 0,1: g = −4, nytt F = 6 − 0,1·(−4) = 6,4.","y = 10, F = 6, lr = 0.1: g = −4, new F = 6 − 0.1·(−4) = 6.4."]}
]},
// ===== 5 Regression, bias/variance & validation =====
{t:5, items:[
 {id:"g-linreg", n:["Lineær regresjon","Linear regression"],
  f:["$f(x) = \\beta_0 + \\beta_1 x_1 + \\dots + \\beta_n x_n$ &nbsp;·&nbsp; $n + 1$ parametre", "$f(x) = \\beta_0 + \\beta_1 x_1 + \\dots + \\beta_n x_n$ &nbsp;·&nbsp; $n + 1$ parameters"],
  e:["β<sub>0</sub> er biasen (verdien ved x = 0) og β<sub>i</sub> stigningstallene. Polynomisk regresjon er fortsatt lineær i parametrene: f(x) = β<sub>0</sub> + β<sub>1</sub>x + … + β<sub>M</sub>x<sup>M</sup>, med genererte features.","β<sub>0</sub> is the bias (the value at x = 0) and β<sub>i</sub> are the slopes. Polynomial regression is still linear in the parameters: f(x) = β<sub>0</sub> + β<sub>1</sub>x + … + β<sub>M</sub>x<sup>M</sup>, with generated features."]},
 {id:"g-mse", n:["Mean squared error","Mean squared error"],
  f:["Notatene: $\\text{MSE} = \\frac{1}{2N} \\sum_i \\left(y^{(i)} - f(x^{(i)})\\right)^2$<br>Vanlig (sklearn): $\\text{MSE} = \\frac{1}{N} \\sum_i \\left(y^{(i)} - \\hat{y}^{(i)}\\right)^2$", "The notes: $\\text{MSE} = \\frac{1}{2N} \\sum_i \\left(y^{(i)} - f(x^{(i)})\\right)^2$<br>Common (sklearn): $\\text{MSE} = \\frac{1}{N} \\sum_i \\left(y^{(i)} - \\hat{y}^{(i)}\\right)^2$"],
  e:["Faktoren ½ er bare for bekvemmelighet: den forsvinner når du deriverer. Les oppgaven nøye for å se hvilken definisjon som brukes. Minimere MSE tilsvarer å maksimere likelihood under Gaussisk støy.","The factor ½ is only for convenience: it cancels when you differentiate. Read the question carefully to see which definition is used. Minimising MSE is the same as maximising the likelihood under Gaussian noise."],
  ex:["y = [3, 5, 2, 7], ŷ = [2, 5, 4, 6]: SSE = 6, MSE (1/N) = 1,5.","y = [3, 5, 2, 7], ŷ = [2, 5, 4, 6]: SSE = 6, MSE (1/N) = 1.5."]},
 {id:"g-linreg-gd", n:["Gradient descent for lineær regresjon","Gradient descent for linear regression"],
  f:["$\\beta_0 \\leftarrow \\beta_0 - \\eta \\frac{1}{N} \\sum_i \\left(f(x^{(i)}) - y^{(i)}\\right)$<br>$\\beta_1 \\leftarrow \\beta_1 - \\eta \\frac{1}{N} \\sum_i x^{(i)} \\left(f(x^{(i)}) - y^{(i)}\\right)$", "$\\beta_0 \\leftarrow \\beta_0 - \\eta \\frac{1}{N} \\sum_i \\left(f(x^{(i)}) - y^{(i)}\\right)$<br>$\\beta_1 \\leftarrow \\beta_1 - \\eta \\frac{1}{N} \\sum_i x^{(i)} \\left(f(x^{(i)}) - y^{(i)}\\right)$"],
  e:["Fra den deriverte av MSE med faktor ½. Hvis modellen overestimerer overalt, er ∂L/∂β<sub>0</sub> > 0, så β<sub>0</sub> minker.","From the derivative of MSE with the factor ½. If the model overestimates everywhere, ∂L/∂β<sub>0</sub> > 0, so β<sub>0</sub> decreases."],
  ex:["(1, 3), (2, 5), β = (0, 1), η = 0,1: feil −2 og −3, β<sub>0</sub> = 0,25, β<sub>1</sub> = 1,4.","(1, 3), (2, 5), β = (0, 1), η = 0.1: errors −2 and −3, β<sub>0</sub> = 0.25, β<sub>1</sub> = 1.4."]},
 {id:"g-r2", n:["R² (forklaringsgrad)","R² (coefficient of determination)"],
  f:["$R^2 = 1 - \\frac{SSE}{SST}$<br>$SSE = \\sum (y - \\hat{y})^2 \\qquad SST = \\sum (y - \\bar{y})^2$", "$R^2 = 1 - \\frac{SSE}{SST}$<br>$SSE = \\sum (y - \\hat{y})^2 \\qquad SST = \\sum (y - \\bar{y})^2$"],
  e:["Andelen av variansen i y som modellen forklarer. 1 er perfekt, 0 er like godt som å alltid predikere ȳ, og negativ er dårligere enn det.","The share of the variance in y that the model explains. 1 is perfect, 0 is as good as always predicting ȳ, and negative is worse than that."]},
 {id:"g-biasvar", n:["Bias–varians-dekomposisjonen","The bias–variance decomposition"],
  f:["$E_D\\left[(y - f(x; D))^2\\right] = \\left(\\text{Bias}_D[f(x; D)]\\right)^2 + \\text{Var}_D[f(x; D)] + \\sigma^2$<br>$\\text{Bias}_D = E_D[f(x; D)] - F(x) \\qquad \\text{Var}_D = E_D\\left[\\left(E_D[f(x; D)] - f(x; D)\\right)^2\\right]$", "$E_D\\left[(y - f(x; D))^2\\right] = \\left(\\text{Bias}_D[f(x; D)]\\right)^2 + \\text{Var}_D[f(x; D)] + \\sigma^2$<br>$\\text{Bias}_D = E_D[f(x; D)] - F(x) \\qquad \\text{Var}_D = E_D\\left[\\left(E_D[f(x; D)] - f(x; D)\\right)^2\\right]$"],
  e:["Forventet feil på et nytt punkt = bias² (systematisk bom, undertilpasning) + varians (sensitivitet for treningsutvalget, overtilpasning) + irredusibel støy σ². Mer kompleksitet gir lavere bias og høyere varians.","The expected error on a new point = bias² (systematic miss, underfitting) + variance (sensitivity to the training sample, overfitting) + irreducible noise σ². More complexity gives lower bias and higher variance."],
  ex:["F = 167, snitt 165, Var = 3, σ² = 1: 2² + 3 + 1 = 8 cm².","F = 167, mean 165, Var = 3, σ² = 1: 2² + 3 + 1 = 8 cm²."]},
 {id:"g-polyfeat", n:["Antall polynomfeatures","Number of polynomial features"],
  f:["Antall monomer av grad $\\le p$ i $d$ variabler $= \\binom{d + p}{p} = \\frac{(d + p)!}{d!\\, p!}$", "Number of monomials of degree $\\le p$ in $d$ variables $= \\binom{d + p}{p} = \\frac{(d + p)!}{d!\\, p!}$"],
  e:["Inkluderer konstantleddet og alle kryssledd (<code>PolynomialFeatures</code>). Graden p er en hyperparameter, og antallet vokser raskt med d og p.","Includes the constant term and all cross terms (<code>PolynomialFeatures</code>). The degree p is a hyperparameter, and the count grows quickly with d and p."],
  ex:["d = 3, p = 2: C(5, 2) = 10 (1 + 3 + 3 kvadrater + 3 kryssledd).","d = 3, p = 2: C(5, 2) = 10 (1 + 3 + 3 squares + 3 cross terms)."]},
 {id:"g-cv", n:["Kryssvalidering","Cross-validation"],
  f:["k-fold: $k$ tilpasninger, hver trent på $\\frac{n(k-1)}{k}$ og testet på $\\frac{n}{k}$<br>LOOCV: $n$ tilpasninger, hver trent på $n - 1$ og testet på 1", "k-fold: $k$ fits, each trained on $\\frac{n(k-1)}{k}$ and tested on $\\frac{n}{k}$<br>LOOCV: $n$ fits, each trained on $n - 1$ and tested on 1"],
  e:["Hver del er test (validering) én gang, og estimatet er snittet av de k resultatene. LOOCV bruker dataene best, men er dyr. k-fold er en billigere mellomting.","Each part is the test (validation) set once, and the estimate is the mean of the k results. LOOCV uses the data best, but is expensive. k-fold is a cheaper compromise."],
  ex:["n = 1000, k = 5: hver modell trenes på 800 og valideres på 200.","n = 1000, k = 5: each model is trained on 800 and validated on 200."]}
]},
// ===== 6 Neural networks =====
{t:6, items:[
 {id:"g-perceptron", n:["Perceptron","Perceptron"],
  f:["$\\hat{y} = H(\\mathbf{w}\\cdot\\mathbf{x} + b)$, der $H(z) = 1$ hvis $z \\ge 0$, ellers 0<br>Læringsregel: $w_i \\leftarrow w_i + \\eta\\, (y - \\hat{y})\\, x_i \\qquad b \\leftarrow b + \\eta\\, (y - \\hat{y})$", "$\\hat{y} = H(\\mathbf{w}\\cdot\\mathbf{x} + b)$, where $H(z) = 1$ if $z \\ge 0$, else 0<br>Learning rule: $w_i \\leftarrow w_i + \\eta\\, (y - \\hat{y})\\, x_i \\qquad b \\leftarrow b + \\eta\\, (y - \\hat{y})$"],
  e:["Én node med stegfunksjon gir en lineær beslutningsgrense, så XOR er umulig. Vektene endres bare når prediksjonen er feil. Eksempler: AND = (1, 1, −1,5), OR = (1, 1, −0,5), NOT = (−1, 0,5).","A single unit with a step function gives a linear decision boundary, so XOR is impossible. The weights only change when the prediction is wrong. Examples: AND = (1, 1, −1.5), OR = (1, 1, −0.5), NOT = (−1, 0.5)."],
  ex:["w = (0,2; −0,4), b = 0,1, x = (1, 1), y = 1, η = 0,5: z = −0,1 gir ŷ = 0, så w = (0,7; 0,1), b = 0,6.","w = (0.2, −0.4), b = 0.1, x = (1, 1), y = 1, η = 0.5: z = −0.1 gives ŷ = 0, so w = (0.7, 0.1), b = 0.6."]},
 {id:"g-neuron", n:["Aktivering i en node","The activation of a unit"],
  f:["$a_j = g\\left(\\sum_i w_{ij}\\, a_i + b_j\\right)$", "$a_j = g\\left(\\sum_i w_{ij}\\, a_i + b_j\\right)$"],
  e:["w<sub>ij</sub> er vekten fra node i i forrige lag til node j, og g er aktiveringsfunksjonen. Regn lag for lag (forward pass). Uten ikke-lineær g blir hele nettverket lineært.","w<sub>ij</sub> is the weight from unit i in the previous layer to unit j, and g is the activation function. Compute layer by layer (forward pass). Without a non-linear g the whole network is linear."],
  ex:["w = [0,5; −1; 2], b = −0,5, x = [2, 1, 0,5], sigmoid: z = 0,5, a ≈ 0,62.","w = [0.5, −1, 2], b = −0.5, x = [2, 1, 0.5], sigmoid: z = 0.5, a ≈ 0.62."]},
 {id:"g-activations", n:["Aktiveringsfunksjoner","Activation functions"],
  f:["$\\sigma(x) = \\frac{1}{1 + e^{-x}} \\qquad \\tanh(x) \\in (-1, 1) \\qquad \\text{ReLU}(x) = \\max(0, x)$<br>leaky ReLU: $x$ hvis $x > 0$, ellers $0{,}1 \\cdot x$", "$\\sigma(x) = \\frac{1}{1 + e^{-x}} \\qquad \\tanh(x) \\in (-1, 1) \\qquad \\text{ReLU}(x) = \\max(0, x)$<br>leaky ReLU: $x$ if $x > 0$, else $0.1 \\cdot x$"],
  e:["Sigmoid gir (0, 1) og passer i utgangen ved binær klassifisering. ReLU er standard i skjulte lag, billig og uten metning for x > 0, men kan gi «døde» noder. Stegfunksjonen har deriverte 0 og kan ikke trenes med backpropagation.","Sigmoid gives (0, 1) and suits the output for binary classification. ReLU is the default in hidden layers, cheap and without saturation for x > 0, but can give “dead” units. The step function has derivative 0 and cannot be trained with backpropagation."]},
 {id:"g-softmax", n:["Softmax","Softmax"],
  f:["$\\text{softmax}(z)_i = \\frac{e^{z_i}}{\\sum_j e^{z_j}}$", "$\\text{softmax}(z)_i = \\frac{e^{z_i}}{\\sum_j e^{z_j}}$"],
  e:["Gjør logits om til en sannsynlighetsfordeling over klassene (positiv, summerer til 1). Brukes i utgangslaget ved flerklasse-klassifisering.","Turns logits into a probability distribution over the classes (positive, sums to 1). Used in the output layer for multi-class classification."],
  ex:["z = [2, 1, 0]: e² / (e² + e + 1) ≈ 7,39/11,1 ≈ 0,67.","z = [2, 1, 0]: e² / (e² + e + 1) ≈ 7.39/11.1 ≈ 0.67."]},
 {id:"g-ce-multi", n:["Cross-entropy for flere klasser","Cross-entropy for several classes"],
  f:["$L(\\hat{y}, y) = -\\sum_i y_i \\log(\\hat{y}_i)$", "$L(\\hat{y}, y) = -\\sum_i y_i \\log(\\hat{y}_i)$"],
  e:["Med one-hot-target teller bare den sanne klassen: L = −log ŷ<sub>sann</sub>. Det er kryss-entropien H(p, q) mellom datafordelingen p og modellens q.","With a one-hot target only the true class counts: L = −log ŷ<sub>true</sub>. It is the cross-entropy H(p, q) between the data distribution p and the model's q."],
  ex:["ŷ = (0,1; 0,1; 0,8), y = (1, 0, 0): L = −ln 0,1 ≈ 2,30.","ŷ = (0.1, 0.1, 0.8), y = (1, 0, 0): L = −ln 0.1 ≈ 2.30."]},
 {id:"g-params", n:["Antall parametre i et Dense-lag","Number of parameters in a Dense layer"],
  f:["$(n_{\\text{inn}} + 1) \\cdot n_{\\text{ut}}$ &nbsp; (vekter + én bias per node); summer over alle lag", "$(n_{\\text{in}} + 1) \\cdot n_{\\text{out}}$ &nbsp; (weights + one bias per unit); sum over all layers"],
  e:["Hver node har én vekt per input og én bias. Inputlaget har ingen parametre.","Each unit has one weight per input and one bias. The input layer has no parameters."],
  ex:["8 → 16 → 4 → 1: 9·16 + 17·4 + 5·1 = 144 + 68 + 5 = 217.","8 → 16 → 4 → 1: 9·16 + 17·4 + 5·1 = 144 + 68 + 5 = 217."]},
 {id:"g-sgd", n:["Epoker, batcher og iterasjoner","Epochs, batches and iterations"],
  f:["Iterasjoner (vektoppdateringer) per epoke $= \\left\\lceil \\frac{N}{\\text{batch\\_size}} \\right\\rceil$", "Iterations (weight updates) per epoch $= \\left\\lceil \\frac{N}{\\text{batch\\_size}} \\right\\rceil$"],
  e:["En epoke er én gjennomgang av alle treningsdataene. Stochastic/mini-batch gradient descent oppdaterer vektene én gang per batch. Den siste, ufullstendige batchen teller også.","An epoch is one pass over all the training data. Stochastic/mini-batch gradient descent updates the weights once per batch. The last, incomplete batch counts too."],
  ex:["N = 10 000, batch 32: ⌈312,5⌉ = 313.","N = 10,000, batch 32: ⌈312.5⌉ = 313."]},
 {id:"g-backprop", n:["Kjerneregelen (backpropagation)","The chain rule (backpropagation)"],
  f:["$\\frac{\\partial f}{\\partial x} = \\frac{\\partial f}{\\partial u} \\cdot \\frac{\\partial u}{\\partial x} \\qquad \\frac{\\partial L}{\\partial w} = \\frac{\\partial L}{\\partial a} \\cdot \\frac{\\partial a}{\\partial z} \\cdot \\frac{\\partial z}{\\partial w}$", "$\\frac{\\partial f}{\\partial x} = \\frac{\\partial f}{\\partial u} \\cdot \\frac{\\partial u}{\\partial x} \\qquad \\frac{\\partial L}{\\partial w} = \\frac{\\partial L}{\\partial a} \\cdot \\frac{\\partial a}{\\partial z} \\cdot \\frac{\\partial z}{\\partial w}$"],
  e:["Backpropagation beregner hvordan hver vekt påvirker tapet ved å bruke kjerneregelen bakover gjennom nettverket. Da trengs deriverbare aktiveringer og tap.","Backpropagation computes how each weight affects the loss by applying the chain rule backwards through the network. This needs differentiable activations and loss."]}
]},
// ===== 7 Clustering =====
{t:7, items:[
 {id:"g-euclid", n:["Euklidsk avstand","Euclidean distance"],
  f:["$d(p, q) = \\sqrt{(p_1 - q_1)^2 + (p_2 - q_2)^2 + \\dots + (p_n - q_n)^2}$", "$d(p, q) = \\sqrt{(p_1 - q_1)^2 + (p_2 - q_2)^2 + \\dots + (p_n - q_n)^2}$"],
  e:["Grunnlaget for k-means, DBSCAN og k-NN. Features med stort tallområde dominerer, så skaler først. I høye dimensjoner blir avstander mindre informative.","The basis of k-means, DBSCAN and k-NN. Features with a large range dominate, so scale first. In high dimensions distances become less informative."],
  ex:["(30, 400) og (60, 410): √(900 + 100) ≈ 31,6.","(30, 400) and (60, 410): √(900 + 100) ≈ 31.6."]},
 {id:"g-kmeans", n:["k-means: tilordning og oppdatering","k-means: assignment and update"],
  f:["Tilordning: $c(x) = \\arg\\min_k d(x, \\mu_k)$<br>Oppdatering: $\\mu_k = \\frac{1}{|C_k|} \\sum_{x \\in C_k} x$", "Assignment: $c(x) = \\arg\\min_k d(x, \\mu_k)$<br>Update: $\\mu_k = \\frac{1}{|C_k|} \\sum_{x \\in C_k} x$"],
  e:["Gjenta de to stegene til sentroidene ikke flytter seg. Resultatet avhenger av startpunktene (lokale minima), og k må velges på forhånd. Klyngene blir konvekse, og alle punkter tilordnes en klynge.","Repeat the two steps until the centroids stop moving. The result depends on the starting points (local minima), and k must be chosen in advance. The clusters are convex, and every point is assigned to a cluster."],
  ex:["1D: 1, 2, 4, 8, 9, 10 med μ = 2 og 4: {1, 2} og {4, 8, 9, 10}, så nye μ = 1,5 og 7,75.","1D: 1, 2, 4, 8, 9, 10 with μ = 2 and 4: {1, 2} and {4, 8, 9, 10}, so new μ = 1.5 and 7.75."]},
 {id:"g-inertia", n:["Inertia","Inertia"],
  f:["$\\text{Inertia} = \\sum_k \\sum_{x \\in C_k} \\lVert x - \\mu_k \\rVert^2$", "$\\text{Inertia} = \\sum_k \\sum_{x \\in C_k} \\lVert x - \\mu_k \\rVert^2$"],
  e:["Summen av kvadrerte avstander til egen sentroide. Lav er kompakt. Den minker alltid med flere klynger (k = n gir 0), så bruk albuen i inertia-plottet for å velge k.","The sum of squared distances to the cluster's own centroid. Low means compact. It always decreases with more clusters (k = n gives 0), so use the elbow in the inertia plot to choose k."],
  ex:["(1, 2), (3, 4), (5, 9): μ = (3, 5), inertia = 13 + 1 + 20 = 34.","(1, 2), (3, 4), (5, 9): μ = (3, 5), inertia = 13 + 1 + 20 = 34."]},
 {id:"g-silhouette", n:["Silhouette-koeffisient","Silhouette coefficient"],
  f:["$s = \\frac{b - a}{\\max(a, b)}$", "$s = \\frac{b - a}{\\max(a, b)}$"],
  e:["a er midlere avstand innad i egen klynge, og b midlere avstand til nærmeste andre klynge. s ∈ [−1, 1]: nær 1 er godt plassert, rundt 0 på grensen, og negativ trolig feil klynge. Høyere snitt er bedre, så velg k med toppen.","a is the mean distance within the point's own cluster, and b the mean distance to the nearest other cluster. s ∈ [−1, 1]: close to 1 is well placed, around 0 on the border, and negative probably the wrong cluster. A higher mean is better, so pick the k at the peak."],
  ex:["a = 2, b = 5: s = 3/5 = 0,6.","a = 2, b = 5: s = 3/5 = 0.6."]},
 {id:"g-dbscan", n:["DBSCAN","DBSCAN"],
  f:["$N_\\varepsilon(p) = \\{q : d(p, q) \\le \\varepsilon\\}$ &nbsp; ($p$ selv er med)<br>Kjernepunkt: $|N_\\varepsilon(p)| \\ge \\text{minPts}$ · Kantpunkt: ikke kjerne, men innenfor $\\varepsilon$ av et kjernepunkt · Støy: resten", "$N_\\varepsilon(p) = \\{q : d(p, q) \\le \\varepsilon\\}$ &nbsp; ($p$ itself included)<br>Core point: $|N_\\varepsilon(p)| \\ge \\text{minPts}$ · Border point: not core, but within $\\varepsilon$ of a core point · Noise: the rest"],
  e:["Klynger vokser fra kjernepunkt til kjernepunkt, så formen kan være vilkårlig (måner, ringer). Antall klynger kommer ut av dataene, og støy får label −1. Avhenger sterkt av ε: for liten gir mye støy, for stor slår klynger sammen.","Clusters grow from core point to core point, so they can take any shape (moons, rings). The number of clusters comes out of the data, and noise gets the label −1. It depends strongly on ε: too small gives a lot of noise, too large merges clusters."],
  ex:["1D: 1, 2, 2,5, 3, 7, 8, 15, ε = 1, minPts = 3: kjernepunkter 2, 2,5 og 3. 1 er kantpunkt, og 7, 8 og 15 er støy.","1D: 1, 2, 2.5, 3, 7, 8, 15, ε = 1, minPts = 3: core points 2, 2.5 and 3. 1 is a border point, and 7, 8 and 15 are noise."]}
]},
// ===== 8 Dimensionality reduction & anomalies =====
{t:8, items:[
 {id:"g-cov", n:["Kovarians og kovariansmatrise","Covariance and the covariance matrix"],
  f:["$\\text{cov}(x_i, x_j) = \\frac{1}{N - 1} \\sum_{k=1}^{N} (x_{i,k} - \\bar{x}_i)(x_{j,k} - \\bar{x}_j)$<br>$S_{ij} = \\text{cov}(x_i, x_j)$", "$\\text{cov}(x_i, x_j) = \\frac{1}{N - 1} \\sum_{k=1}^{N} (x_{i,k} - \\bar{x}_i)(x_{j,k} - \\bar{x}_j)$<br>$S_{ij} = \\text{cov}(x_i, x_j)$"],
  e:["Diagonalen i S er variansene, og resten er kovariansene. S er symmetrisk. Sentrer dataene (trekk fra snittet) før PCA. Notatene deler på N − 1.","The diagonal of S holds the variances, and the rest are covariances. S is symmetric. Centre the data (subtract the mean) before PCA. The notes divide by N − 1."],
  ex:["x<sub>1</sub> = (1, 2, 3), x<sub>2</sub> = (2, 1, 0): cov = (−1 + 0 − 1)/2 = −1.","x<sub>1</sub> = (1, 2, 3), x<sub>2</sub> = (2, 1, 0): cov = (−1 + 0 − 1)/2 = −1."]},
 {id:"g-eigen", n:["Egenverdier og egenvektorer","Eigenvalues and eigenvectors"],
  f:["$\\det(S - \\lambda I) = 0$ gir $\\lambda$ &nbsp;·&nbsp; $S\\mathbf{v} = \\lambda \\mathbf{v}$ gir $\\mathbf{v}$ &nbsp;·&nbsp; $\\sum \\lambda = \\text{spor}(S)$", "$\\det(S - \\lambda I) = 0$ gives $\\lambda$ &nbsp;·&nbsp; $S\\mathbf{v} = \\lambda \\mathbf{v}$ gives $\\mathbf{v}$ &nbsp;·&nbsp; $\\sum \\lambda = \\text{trace}(S)$"],
  e:["Hovedkomponentene er egenvektorene til S, sortert etter egenverdi. λ er variansen langs komponenten. Komponentene er ortogonale. Normer egenvektorene til lengde 1.","The principal components are the eigenvectors of S, sorted by eigenvalue. λ is the variance along the component. The components are orthogonal. Normalise the eigenvectors to length 1."],
  ex:["S = [[2, 1], [1, 2]]: λ = 3 og 1, PC1 = (1/√2)(1, 1).","S = [[2, 1], [1, 2]]: λ = 3 and 1, PC1 = (1/√2)(1, 1)."]},
 {id:"g-explvar", n:["Forklart varians","Explained variance"],
  f:["Andel for $\\text{PC}_k = \\frac{\\lambda_k}{\\sum_j \\lambda_j}$<br>Kumulativ for de $k$ første $= \\frac{\\lambda_1 + \\dots + \\lambda_k}{\\sum_j \\lambda_j}$", "Share for $\\text{PC}_k = \\frac{\\lambda_k}{\\sum_j \\lambda_j}$<br>Cumulative for the first $k$ $= \\frac{\\lambda_1 + \\dots + \\lambda_k}{\\sum_j \\lambda_j}$"],
  e:["Velg det minste antallet komponenter som når ønsket andel (f.eks. 90 %), eller se etter knekken i scree-plottet. Del egenverdiene på summen før du leser av andeler. Mest varians er ikke alltid mest nyttig for klassifisering.","Choose the smallest number of components that reaches the desired share (e.g. 90 %), or look for the bend in the scree plot. Divide the eigenvalues by their sum before reading off shares. Most variance is not always most useful for classification."],
  ex:["λ = 4, 2, 1, 0,5, 0,5: de to første forklarer 6/8 = 75 %.","λ = 4, 2, 1, 0.5, 0.5: the first two explain 6/8 = 75 %."]},
 {id:"g-project", n:["Projeksjon og rekonstruksjon","Projection and reconstruction"],
  f:["$z_k = \\mathbf{e}_k^\\top (\\mathbf{x} - \\bar{\\mathbf{x}}) \\qquad \\hat{\\mathbf{x}} = \\bar{\\mathbf{x}} + \\sum_k z_k\\, \\mathbf{e}_k$<br>Rekonstruksjonsfeil $= \\lVert \\mathbf{x} - \\hat{\\mathbf{x}} \\rVert^2$", "$z_k = \\mathbf{e}_k^\\top (\\mathbf{x} - \\bar{\\mathbf{x}}) \\qquad \\hat{\\mathbf{x}} = \\bar{\\mathbf{x}} + \\sum_k z_k\\, \\mathbf{e}_k$<br>Reconstruction error $= \\lVert \\mathbf{x} - \\hat{\\mathbf{x}} \\rVert^2$"],
  e:["z er de nye koordinatene (features) etter PCA. Med færre komponenter enn features mister du informasjon. Høy rekonstruksjonsfeil (PCA eller autoencoder) tyder på et uvanlig punkt, og kan brukes til anomalideteksjon.","z are the new coordinates (features) after PCA. With fewer components than features you lose information. A high reconstruction error (PCA or autoencoder) suggests an unusual point, and can be used for anomaly detection."],
  ex:["x − x̄ = (3, 1), e<sub>1</sub> = (1/√2)(1, 1): z<sub>1</sub> ≈ 2,83, x̂ − x̄ = (2, 2), feil = 2.","x − x̄ = (3, 1), e<sub>1</sub> = (1/√2)(1, 1): z<sub>1</sub> ≈ 2.83, x̂ − x̄ = (2, 2), error = 2."]},
 {id:"g-tsne", n:["t-SNE (ingen formel å regne)","t-SNE (no formula to compute)"],
  f:["Bevarer <i>lokale</i> naboskap · ingen gjenbrukbar projeksjon · <code>fit_transform</code> på nytt for nye data","Preserves <i>local</i> neighbourhoods · no reusable projection · <code>fit_transform</code> again for new data"],
  e:["t-SNE optimerer plasseringen av punktene direkte i 2D/3D i stedet for å lære en transformasjon. Avstander mellom klynger og klyngestørrelser i plottet betyr lite. Bruk det til visualisering, ikke som features.","t-SNE optimises the positions of the points directly in 2D/3D instead of learning a transform. Distances between clusters and cluster sizes in the plot mean little. Use it for visualisation, not as features."]},
 {id:"g-anomaly", n:["Anomalideteksjon","Anomaly detection"],
  f:["Isolation Forest: antall flagget $\\approx \\text{contamination} \\cdot n$; kort snittlig stilengde = anomali<br>k-means: skår $= \\min_k \\lVert x - \\mu_k \\rVert$ over en terskel · DBSCAN: støypunkter ($-1$)", "Isolation Forest: number flagged $\\approx \\text{contamination} \\cdot n$; short mean path length = anomaly<br>k-means: score $= \\min_k \\lVert x - \\mu_k \\rVert$ above a threshold · DBSCAN: noise points ($-1$)"],
  e:["Anomalier er få og annerledes, så de isoleres med få tilfeldige splitter. contamination er din antakelse om andelen anomalier og bestemmer terskelen.","Anomalies are few and different, so they are isolated with few random splits. contamination is your assumption about the share of anomalies and sets the threshold."],
  ex:["n = 1500, contamination = 0,02: ≈ 30 punkter flagges.","n = 1500, contamination = 0.02: ≈ 30 points are flagged."]}
]},
// ===== 9 Reinforcement learning =====
{t:9, items:[
 {id:"g-return", n:["Diskontert retur","Discounted return"],
  f:["$G_t = R_{t+1} + \\gamma R_{t+2} + \\gamma^2 R_{t+3} + \\dots = \\sum_{k \\ge 0} \\gamma^k R_{t+k+1}$<br>$\\sum_{k \\ge 0} \\gamma^k = \\frac{1}{1 - \\gamma}$", "$G_t = R_{t+1} + \\gamma R_{t+2} + \\gamma^2 R_{t+3} + \\dots = \\sum_{k \\ge 0} \\gamma^k R_{t+k+1}$<br>$\\sum_{k \\ge 0} \\gamma^k = \\frac{1}{1 - \\gamma}$"],
  e:["En belønning k steg frem vektes med γ<sup>k</sup>, og den første (R<sub>t+1</sub>) har vekt 1. Liten γ gir en kortsiktig agent, stor γ en langsiktig. Med γ < 1 blir en uendelig sum endelig.","A reward k steps ahead is weighted by γ<sup>k</sup>, and the first one (R<sub>t+1</sub>) has weight 1. A small γ gives a short-sighted agent, a large γ a far-sighted one. With γ < 1 an infinite sum becomes finite."],
  ex:["R = 1, 0, 2 og γ = 0,9: 1 + 0 + 0,81·2 = 2,62. Konstant R = 2, γ = 0,95: 2/0,05 = 40.","R = 1, 0, 2 and γ = 0.9: 1 + 0 + 0.81·2 = 2.62. Constant R = 2, γ = 0.95: 2/0.05 = 40."]},
 {id:"g-qlearning", n:["Q-learning (Bellman-oppdatering)","Q-learning (Bellman update)"],
  f:["$Q_{\\text{new}}(S_t, A_t) \\leftarrow (1 - \\alpha)\\, Q(S_t, A_t) + \\alpha \\left(R_{t+1} + \\gamma \\max_A Q(S_{t+1}, A)\\right)$", "$Q_{\\text{new}}(S_t, A_t) \\leftarrow (1 - \\alpha)\\, Q(S_t, A_t) + \\alpha \\left(R_{t+1} + \\gamma \\max_A Q(S_{t+1}, A)\\right)$"],
  e:["α er læringsraten: α = 0 lærer ingenting og α = 1 glemmer den gamle verdien. γ er diskonteringsfaktoren. Målet R + γ·max Q bruker den beste handlingen i neste tilstand.","α is the learning rate: α = 0 learns nothing and α = 1 forgets the old value. γ is the discount factor. The target R + γ·max Q uses the best action in the next state."],
  ex:["Q = 1, α = 0,1, R = −1, γ = 0,95, max Q′ = 6: 0,9 + 0,1·4,7 = 1,37.","Q = 1, α = 0.1, R = −1, γ = 0.95, max Q′ = 6: 0.9 + 0.1·4.7 = 1.37."]},
 {id:"g-vq", n:["Verdi og Q-verdi (deterministisk)","Value and Q-value (deterministic)"],
  f:["$V(s) = \\max_a Q(s, a) \\qquad Q(s, a) = R(s, a) + \\gamma\\, V(s') \\qquad \\pi(s) = \\arg\\max_a Q(s, a)$", "$V(s) = \\max_a Q(s, a) \\qquad Q(s, a) = R(s, a) + \\gamma\\, V(s') \\qquad \\pi(s) = \\arg\\max_a Q(s, a)$"],
  e:["s′ er tilstanden handlingen a fører til. En terminal tilstand (hull eller mål) har ingen fremtid, så Q = bare belønningen. Den grådige policyen velger handlingen med størst Q.","s′ is the state that action a leads to. A terminal state (hole or goal) has no future, so Q = just the reward. The greedy policy picks the action with the largest Q."],
  ex:["Frozen Lake, γ = 0,9, 6 steg til 🎁: V(start) = 0,9<sup>5</sup> ≈ 0,59.","Frozen Lake, γ = 0.9, 6 steps to 🎁: V(start) = 0.9<sup>5</sup> ≈ 0.59."]},
 {id:"g-egreedy", n:["ε-greedy","ε-greedy"],
  f:["$P(\\text{grådig}) = (1 - \\varepsilon) + \\frac{\\varepsilon}{|A|} \\qquad P(\\text{annen handling}) = \\frac{\\varepsilon}{|A|}$<br>(tilfeldig valg blant alle $|A|$)", "$P(\\text{greedy}) = (1 - \\varepsilon) + \\frac{\\varepsilon}{|A|} \\qquad P(\\text{other action}) = \\frac{\\varepsilon}{|A|}$<br>(random pick among all $|A|$)"],
  e:["Med sannsynlighet ε utforsker agenten (tilfeldig handling), ellers utnytter den (argmax Q). Det tilfeldige valget kan også treffe den grådige handlingen.","With probability ε the agent explores (random action), otherwise it exploits (argmax Q). The random pick can also land on the greedy action."],
  ex:["ε = 0,2, 4 handlinger: P(grådig) = 0,8 + 0,05 = 0,85.","ε = 0.2, 4 actions: P(greedy) = 0.8 + 0.05 = 0.85."]},
 {id:"g-edecay", n:["Epsilon decay","Epsilon decay"],
  f:["$\\varepsilon \\leftarrow \\max(\\varepsilon_{\\min},\\ \\varepsilon \\cdot \\text{decay})$ $\\;\\Rightarrow\\;$ $\\varepsilon_n = \\max(\\varepsilon_{\\min},\\ \\varepsilon_0 \\cdot \\text{decay}^n)$<br>$n = \\frac{\\ln(\\varepsilon_{\\min} / \\varepsilon_0)}{\\ln(\\text{decay})}$", "$\\varepsilon \\leftarrow \\max(\\varepsilon_{\\min},\\ \\varepsilon \\cdot \\text{decay})$ $\\;\\Rightarrow\\;$ $\\varepsilon_n = \\max(\\varepsilon_{\\min},\\ \\varepsilon_0 \\cdot \\text{decay}^n)$<br>$n = \\frac{\\ln(\\varepsilon_{\\min} / \\varepsilon_0)}{\\ln(\\text{decay})}$"],
  e:["Høy ε tidlig (mye utforsking) og lav ε senere (utnytt det som er lært). Geometrisk decay er ikke det samme som å trekke fra en fast verdi.","A high ε early (much exploration) and a low ε later (exploit what has been learned). Geometric decay is not the same as subtracting a fixed amount."],
  ex:["ε<sub>0</sub> = 1, decay = 0,99: ε<sub>100</sub> ≈ 0,37, og ε<sub>min</sub> = 0,05 nås etter ≈ 298 episoder.","ε<sub>0</sub> = 1, decay = 0.99: ε<sub>100</sub> ≈ 0.37, and ε<sub>min</sub> = 0.05 is reached after ≈ 298 episodes."]},
 {id:"g-dqn", n:["Deep Q-learning (DQN)","Deep Q-learning (DQN)"],
  f:["$y = R + \\gamma \\max_{a'} Q_{\\text{target}}(S', a')$ &nbsp; ($y = R$ hvis terminal)<br>$\\text{Loss} = \\left(y - Q(S, A)\\right)^2$", "$y = R + \\gamma \\max_{a'} Q_{\\text{target}}(S', a')$ &nbsp; ($y = R$ if terminal)<br>$\\text{Loss} = \\left(y - Q(S, A)\\right)^2$"],
  e:["Et nevralt nett erstatter Q-tabellen. Target network (oppdateres sjeldnere) gir et stabilt mål, og en replay buffer gir mindre korrelerte treningsdata. Lossen er MSE, og den backpropageres gjennom Q-nettet.","A neural network replaces the Q table. The target network (updated less often) gives a stable target, and a replay buffer gives less correlated training data. The loss is MSE, and it is backpropagated through the Q network."],
  ex:["R = 0, γ = 0,9, max Q<sub>target</sub> = 0,5, Q = 0,3: y = 0,45, loss = 0,0225.","R = 0, γ = 0.9, max Q<sub>target</sub> = 0.5, Q = 0.3: y = 0.45, loss = 0.0225."]}
]},
// ===== 10 XAI =====
{t:10, items:[
 {id:"g-shapley", n:["Shapley-verdi","Shapley value"],
  f:["$\\varphi_i = \\sum_{S \\subseteq N \\setminus \\{i\\}} \\frac{|S|!\\,(n - |S| - 1)!}{n!} \\left[v(S \\cup \\{i\\}) - v(S)\\right]$", "$\\varphi_i = \\sum_{S \\subseteq N \\setminus \\{i\\}} \\frac{|S|!\\,(n - |S| - 1)!}{n!} \\left[v(S \\cup \\{i\\}) - v(S)\\right]$"],
  e:["Snittet av spiller i sitt marginale bidrag over alle rekkefølger spillerne kan ankomme i. v er den karakteristiske funksjonen (verdien av en koalisjon). Egenskaper: efficiency, symmetry, dummy og additivity.","The mean of player i's marginal contribution over all orders in which the players can arrive. v is the characteristic function (the value of a coalition). Properties: efficiency, symmetry, dummy and additivity."],
  ex:["v(A) = 10, v(B) = 20, v(AB) = 40: φ<sub>A</sub> = ½(10 − 0) + ½(40 − 20) = 15.","v(A) = 10, v(B) = 20, v(AB) = 40: φ<sub>A</sub> = ½(10 − 0) + ½(40 − 20) = 15."]},
 {id:"g-shap-eff", n:["SHAP: lokal nøyaktighet","SHAP: local accuracy"],
  f:["$f(x) = \\varphi_0 + \\sum_i \\varphi_i, \\qquad \\varphi_0 = E[f(x)]$", "$f(x) = \\varphi_0 + \\sum_i \\varphi_i, \\qquad \\varphi_0 = E[f(x)]$"],
  e:["SHAP-verdiene for én prediksjon summerer til avviket fra basisverdien (snittprediksjonen). Det er dette waterfall-plottet viser. Global viktighet er snittet av |φ<sub>i</sub>| over mange punkter.","The SHAP values for one prediction sum to the difference from the base value (the mean prediction). This is what the waterfall plot shows. Global importance is the mean of |φ<sub>i</sub>| over many points."],
  ex:["φ<sub>0</sub> = 0,30, f(x) = 0,72, φ<sub>Age</sub> = 0,10, φ<sub>Fare</sub> = −0,05: φ<sub>Sex</sub> = 0,37.","φ<sub>0</sub> = 0.30, f(x) = 0.72, φ<sub>Age</sub> = 0.10, φ<sub>Fare</sub> = −0.05: φ<sub>Sex</sub> = 0.37."]},
 {id:"g-coalitions", n:["Antall koalisjoner","Number of coalitions"],
  f:["Antall delmengder av $n$ spillere $= 2^n$", "Number of subsets of $n$ players $= 2^n$"],
  e:["En eksakt Shapley-beregning må i prinsippet evaluere v for alle koalisjoner. Derfor bruker SHAP tilnærminger (sampling, KernelSHAP, TreeSHAP). I Image SHAP er superpikslene spillerne.","An exact Shapley computation must in principle evaluate v for every coalition. That is why SHAP uses approximations (sampling, KernelSHAP, TreeSHAP). In Image SHAP the superpixels are the players."],
  ex:["20 superpiksler: 2<sup>20</sup> = 1 048 576 koalisjoner.","20 superpixels: 2<sup>20</sup> = 1,048,576 coalitions."]},
 {id:"g-tcav", n:["TCAV-skår","TCAV score"],
  f:["$\\text{TCAV}_{C,k,l} = \\frac{|\\{x \\in X_k : S_{C,k,l}(x) > 0\\}|}{|X_k|}$", "$\\text{TCAV}_{C,k,l} = \\frac{|\\{x \\in X_k : S_{C,k,l}(x) > 0\\}|}{|X_k|}$"],
  e:["Andelen bilder av klasse k der en bevegelse i retning av konseptet C (konseptvektoren, CAV) i lag l øker skåren for k. Et globalt, modellspesifikt mål på hvor viktig et menneskelig konsept er.","The share of images of class k where moving in the direction of concept C (the concept vector, CAV) in layer l increases the score for k. A global, model-specific measure of how important a human concept is."],
  ex:["112 av 160 sebrabilder har S > 0: TCAV = 0,70.","112 of 160 zebra images have S > 0: TCAV = 0.70."]}
]},
// ===== 11 AI Act =====
{t:11, items:[
 {id:"g-fines", n:["Bøter (Artikkel 99)","Fines (Article 99)"],
  f:["Forbudt praksis (Art. 5): inntil $\\max\\left(\\text{35 mill. EUR},\\ 7\\,\\% \\times \\text{global årsomsetning}\\right)$<br>De fleste andre brudd: inntil $\\max\\left(\\text{15 mill. EUR},\\ 3\\,\\% \\times \\text{omsetning}\\right)$", "Prohibited practices (Art. 5): up to $\\max\\left(\\text{EUR 35M},\\ 7\\,\\% \\times \\text{global annual turnover}\\right)$<br>Most other breaches: up to $\\max\\left(\\text{EUR 15M},\\ 3\\,\\% \\times \\text{turnover}\\right)$"],
  e:["Det <b>høyeste</b> av det faste beløpet og prosentandelen gjelder. Regn ut begge og velg det største.","The <b>higher</b> of the fixed amount and the percentage applies. Compute both and take the larger."],
  ex:["Omsetning €2 mrd., forbud: 7 % = €140 mill. > €35 mill. Omsetning €300 mill., høyrisiko: 3 % = €9 mill. < €15 mill., så €15 mill.","Turnover €2bn, prohibition: 7 % = €140M > €35M. Turnover €300M, high-risk: 3 % = €9M < €15M, so €15M."]},
 {id:"g-gpai", n:["GPAI og systemisk risiko (Artikkel 51)","GPAI and systemic risk (Article 51)"],
  f:["Treningsberegning: $C \\approx 6 \\cdot N \\cdot D$ FLOP &nbsp; ($N$ = parametre, $D$ = treningstokens)<br>$C > 10^{25}$ FLOP $\\Rightarrow$ antatt systemisk risiko", "Training compute: $C \\approx 6 \\cdot N \\cdot D$ FLOP &nbsp; ($N$ = parameters, $D$ = training tokens)<br>$C > 10^{25}$ FLOP $\\Rightarrow$ presumed systemic risk"],
  e:["Over terskelen antas en GPAI-modell å ha systemisk risiko, med ekstra plikter. Kommisjonen kan også utpeke modeller under terskelen (Anneks 13). Høy beregning gjør ikke en modell til et høyrisikosystem; det er en annen kategori.","Above the threshold a GPAI model is presumed to have systemic risk, with extra obligations. The Commission can also designate models below the threshold (Annex 13). High compute does not make a model a high-risk system; that is a different category."],
  ex:["N = 7·10<sup>10</sup>, D = 1,5·10<sup>13</sup>: C ≈ 6,3·10<sup>24</sup> < 10<sup>25</sup>.","N = 7·10<sup>10</sup>, D = 1.5·10<sup>13</sup>: C ≈ 6.3·10<sup>24</sup> < 10<sup>25</sup>."]},
 {id:"g-dates", n:["Datoer og måneder","Dates and months"],
  f:["Måneder mellom to datoer (samme dag i måneden) $= 12 \\cdot \\Delta\\text{år} + \\Delta\\text{måned}$<br>Ikrafttredelse 1. august 2024", "Months between two dates (same day of month) $= 12 \\cdot \\Delta\\text{years} + \\Delta\\text{months}$<br>Entry into force 1 August 2024"],
  e:["Opprinnelig innfasing etter ikrafttredelse: forbud 6 mnd. → GPAI 12 mnd. → hoveddelen 24 mnd. (2. aug. 2026) → Anneks 1-høyrisiko 36 mnd. Digital Omnibus (2026) utsatte høyrisikokravene til 2. des. 2027 (Anneks 3) og 2. aug. 2028 (Anneks 1).","Original phase-in after entry into force: prohibitions 6 months → GPAI 12 months → main part 24 months (2 Aug 2026) → Annex 1 high risk 36 months. The Digital Omnibus (2026) postponed the high-risk requirements to 2 Dec 2027 (Annex 3) and 2 Aug 2028 (Annex 1)."],
  ex:["2. aug. 2026 → 2. des. 2027: 12·1 + 4 = 16 måneder.","2 Aug 2026 → 2 Dec 2027: 12·1 + 4 = 16 months."]}
]}
];
})();
